import org.joda.time.field.DecoratedDurationField;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class GJChronology_getInstance_TriageGen1Test {









    @Test
    public void testGetInstance_CacheMiss_DifferentParams() {
        // Tests that different minDaysInFirstWeek results in a new instance (not a cache hit)
        DateTimeZone zone = DateTimeZone.UTC;

        GJChronology chrono1 = GJChronology.getInstance(zone, null, 4);
        GJChronology chrono2 = GJChronology.getInstance(zone, null, 7);

        assertNotSame(chrono1, chrono2);
        assertEquals(4, chrono1.getMinimumDaysInFirstWeek());
        assertEquals(7, chrono2.getMinimumDaysInFirstWeek());
    }




}
